def recolor_majority(grid, bg=None):
    """Background (majority) cells become 0; every other cell becomes the background color."""
    if bg is None:
        from collections import Counter
        bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    return [[bg if v != bg else 0 for v in row] for row in grid]

from lib import recolor_majority

def transform(grid):
    return recolor_majority(grid)

